#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

PROJECT_ID="comfforts-369117"
REGION="us-west1"
REPOSITORY="hankgalt/ai_finance_assitant"
GITHUB_ENVIRONMENT="staging"
BACKEND_SERVICE="aifa-staging-backend"
RUNTIME_SECRET_ID="aifa-staging-qdrant-runtime-api-key"
STAGING_BUCKET="comfforts-369117-aifa-tf-staging"
QDRANT_CONSOLE_URL="https://cloud.qdrant.io/"
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/../../.." && pwd)
WORKLOAD_ROOT="$REPO_ROOT/infrastructure/terraform/environments/staging-workloads"
CONTRACT="$REPO_ROOT/contracts/deployment/runtime-key-rotation.v1.json"
EVIDENCE_DIR="$REPO_ROOT/backend/artifacts/knowledge/deployment"
PYTHON="$REPO_ROOT/backend/.venv/bin/python"
TEMP_DIR=$(mktemp -d "${TMPDIR:-/tmp}/aifa-runtime-key-rotation.XXXXXX")
PLAN_FILE="$TEMP_DIR/rotation.tfplan"
PLAN_JSON="$TEMP_DIR/rotation.tfplan.json"
SERVICE_DESCRIPTION_FILE="$TEMP_DIR/backend-service.json"
IAM_POLICY_FILE="$TEMP_DIR/backend-iam.json"
trap 'rm -f "$PLAN_FILE" "$PLAN_JSON" "$SERVICE_DESCRIPTION_FILE" "$IAM_POLICY_FILE"; rmdir "$TEMP_DIR" 2>/dev/null || true' EXIT

# Refresh the exact non-secret backend and IAM readbacks used by every gate.
refresh_backend_readback() {
  gcloud run services describe "$BACKEND_SERVICE" \
    --project="$PROJECT_ID" --region="$REGION" --format=json > "$SERVICE_DESCRIPTION_FILE"
  gcloud run services get-iam-policy "$BACKEND_SERVICE" \
    --project="$PROJECT_ID" --region="$REGION" --format=json > "$IAM_POLICY_FILE"
  DEPLOYED_VERSION=$(jq -er '
    .spec.template.spec.containers[] |
    select(.name == "backend") |
    .env[] |
    select(.name == "AIFA_QDRANT_API_KEY") |
    (.valueFrom.secretKeyRef.version // .valueFrom.secretKeyRef.key) | tostring
  ' "$SERVICE_DESCRIPTION_FILE")
}

# Verify the cutover did not change image, provider posture, or origin controls.
verify_backend_version() {
  local expected_version="$1" direct_url
  refresh_backend_readback
  jq -e --arg image "$BACKEND_IMAGE" --arg version "$expected_version" '
    (.spec.template.spec.containers[] | select(.name == "backend")) as $backend |
    ($backend.env // []) as $env |
    .metadata.name == "aifa-staging-backend" and
    .metadata.annotations["run.googleapis.com/ingress"] == "internal-and-cloud-load-balancing" and
    .metadata.annotations["run.googleapis.com/default-url-disabled"] == "true" and
    any(.status.conditions[]?; .type == "Ready" and .status == "True") and
    $backend.image == $image and
    any($env[];
      .name == "AIFA_QDRANT_API_KEY" and
      (.valueFrom.secretKeyRef.secret // .valueFrom.secretKeyRef.name) ==
        "aifa-staging-qdrant-runtime-api-key" and
      ((.valueFrom.secretKeyRef.version // .valueFrom.secretKeyRef.key) | tostring) == $version
    ) and
    any($env[]; .name == "AIFA_PROVIDER_MODE" and .value == "credential_free") and
    any($env[]; .name == "AIFA_MODEL_MODE" and .value == "credential_free") and
    all($env[];
      (.name | ascii_upcase) as $name |
      [
        "AIFA_ALPHA_VANTAGE_API_KEY",
        "AIFA_ALPHA_VANTAGE_TERMS_APPROVED",
        "AIFA_MASSIVE_API_KEY",
        "AIFA_MASSIVE_TERMS_APPROVED",
        "AIFA_OPENAI_API_KEY",
        "AIFA_OPENAI_TERMS_APPROVED",
        "AIFA_TAVILY_API_KEY",
        "AIFA_TAVILY_TERMS_APPROVED",
        "OPENAI_API_KEY"
      ] | index($name) == null
    )
  ' "$SERVICE_DESCRIPTION_FILE" >/dev/null || return 1
  jq -e 'all(.bindings[]?.members[]?; . != "allUsers" and . != "allAuthenticatedUsers")' \
    "$IAM_POLICY_FILE" >/dev/null || return 1
  direct_url=$(jq -r '.status.url // empty' "$SERVICE_DESCRIPTION_FILE")
  if [[ -n "$direct_url" ]] && \
    curl --silent --show-error --fail --max-time 15 "$direct_url/api/health/live" \
      >/dev/null 2>&1; then
    warn "backend accepted anonymous direct-origin traffic"
    return 1
  fi
}

# Build a saved plan and require that only the numeric Qdrant version changes.
prepare_rotation_plan() {
  local old_version="$1" new_version="$2" plan_exit=0
  export TF_VAR_project_id="$PROJECT_ID"
  export TF_VAR_region="$REGION"
  export TF_VAR_backend_image="$BACKEND_IMAGE"
  export TF_VAR_frontend_image="$FRONTEND_IMAGE"
  export TF_VAR_qdrant_secret_version="$new_version"
  rm -f "$PLAN_FILE" "$PLAN_JSON"
  terraform -chdir="$WORKLOAD_ROOT" init -reconfigure \
    -backend-config="bucket=$STAGING_BUCKET" \
    -backend-config="prefix=workloads"
  terraform -chdir="$WORKLOAD_ROOT" plan -lock-timeout=5m -detailed-exitcode \
    -out="$PLAN_FILE" || plan_exit=$?
  [[ "$plan_exit" -eq 2 ]] || {
    warn "expected one backend update, but Terraform plan exit code was $plan_exit"
    return 1
  }
  terraform -chdir="$WORKLOAD_ROOT" show -json "$PLAN_FILE" > "$PLAN_JSON"
  "$PYTHON" -m ai_finance_assistant.knowledge.runtime_key_rotation \
    --repo-root "$REPO_ROOT" --contract "$CONTRACT" validate-plan \
    --plan-json "$PLAN_JSON" --old-version "$old_version" --new-version "$new_version"
  terraform -chdir="$WORKLOAD_ROOT" show -no-color "$PLAN_FILE"
}

# Apply a separately reviewed rollback while the old credential remains valid.
rollback_to_old_version() {
  warn "The replacement cutover did not pass readback; the old Qdrant key remains active."
  confirm "Create, review, and apply the backend-only rollback to version $OLD_VERSION now?" || return 1
  prepare_rotation_plan "$NEW_VERSION" "$OLD_VERSION"
  confirm "Apply the displayed rollback plan?" || return 1
  terraform -chdir="$WORKLOAD_ROOT" apply "$PLAN_FILE"
  verify_backend_version "$OLD_VERSION"
}

banner "Qdrant runtime-key rotation"

# Establish immutable revision, identities, current variables, and backend state.
stage "Verify revision, identity, and current deployment"
for tool in git gh gcloud jq curl terraform; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not available on PATH"; exit 1; }
done
[[ -x "$PYTHON" ]] || { warn "backend virtual environment is missing; run make backend-sync"; exit 1; }
cd "$REPO_ROOT"
[[ "$(git branch --show-current)" == "main" ]] || { warn "switch to main before rotating"; exit 1; }
WORKTREE_STATUS=$(git status --porcelain)
if [[ -n "$WORKTREE_STATUS" ]]; then
  ROTATION_EVIDENCE_CHANGES=0
  while IFS= read -r status_line; do
    status_path="${status_line:3}"
    [[ "$status_path" == backend/artifacts/knowledge/deployment/staging-runtime-key-rotation-*.json ]] || {
      warn "the worktree may contain only one in-progress runtime-key evidence file"
      exit 1
    }
    ROTATION_EVIDENCE_CHANGES=$((ROTATION_EVIDENCE_CHANGES + 1))
  done <<< "$WORKTREE_STATUS"
  [[ "$ROTATION_EVIDENCE_CHANGES" -eq 1 ]] || {
    warn "multiple in-progress runtime-key evidence files are not accepted"
    exit 1
  }
fi
git fetch origin main --quiet
[[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/main)" ]] || {
  warn "local main must exactly match origin/main"
  exit 1
}
gh auth status >/dev/null
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
[[ "$ACTIVE_ACCOUNT" == "vtalwar.w@comfforts.com" ]] || {
  warn "active gcloud account must be vtalwar.w@comfforts.com"
  exit 1
}
[[ "$(gcloud config get-value project 2>/dev/null)" == "$PROJECT_ID" ]] || {
  warn "active gcloud project must be $PROJECT_ID"
  exit 1
}
REVISION=$(git rev-parse HEAD)
VARIABLE_VERSION=$(gh variable get GCP_QDRANT_SECRET_VERSION \
  --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT")
[[ "$VARIABLE_VERSION" =~ ^[1-9][0-9]*$ ]] || {
  warn "staging GCP_QDRANT_SECRET_VERSION must be a positive numeric version"
  exit 1
}
BACKEND_IMAGE=$(gh variable get GCP_BACKEND_IMAGE \
  --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT")
FRONTEND_IMAGE=$(gh variable get GCP_FRONTEND_IMAGE \
  --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT")
for image in "$BACKEND_IMAGE" "$FRONTEND_IMAGE"; do
  [[ "$image" == us-west1-docker.pkg.dev/comfforts-369117/aifa-containers/*@sha256:* ]] || {
    warn "staging deployment images must be digest-pinned in the approved Artifact Registry"
    exit 1
  }
done
refresh_backend_readback
RESUME_EVIDENCE=""
shopt -s nullglob
for candidate in "$EVIDENCE_DIR"/staging-runtime-key-rotation-"$REVISION"-v*-to-v*.json; do
  candidate_status=$(jq -er '.status' "$candidate")
  case "$candidate_status" in
    qualified_apply_pending|qualified_old_key_revocation_pending|qualified_old_secret_cleanup_pending)
      [[ -z "$RESUME_EVIDENCE" ]] || { warn "multiple incomplete rotation records exist"; exit 1; }
      RESUME_EVIDENCE="$candidate"
      ;;
  esac
done
shopt -u nullglob
if [[ -n "$RESUME_EVIDENCE" ]]; then
  EVIDENCE="$RESUME_EVIDENCE"
  EVIDENCE_STATUS=$(jq -er '.status' "$EVIDENCE")
  OLD_VERSION=$(jq -er '.rotation.old_secret_version' "$EVIDENCE")
  NEW_VERSION=$(jq -er '.rotation.new_secret_version' "$EVIDENCE")
  if [[ "$EVIDENCE_STATUS" == "qualified_apply_pending" ]]; then
    [[ "$VARIABLE_VERSION" == "$OLD_VERSION" || "$VARIABLE_VERSION" == "$NEW_VERSION" ]] || {
      warn "incomplete evidence does not match the GitHub version variable"
      exit 1
    }
    [[ "$DEPLOYED_VERSION" == "$OLD_VERSION" || "$DEPLOYED_VERSION" == "$NEW_VERSION" ]] || {
      warn "incomplete evidence does not match the deployed backend version"
      exit 1
    }
    [[ "$VARIABLE_VERSION" != "$NEW_VERSION" || "$DEPLOYED_VERSION" == "$NEW_VERSION" ]] || {
      warn "GitHub selects the replacement but the backend does not; restore reviewed state first"
      exit 1
    }
  else
    [[ "$VARIABLE_VERSION" == "$NEW_VERSION" && "$DEPLOYED_VERSION" == "$NEW_VERSION" ]] || {
      warn "incomplete evidence does not match the completed cutover"
      exit 1
    }
  fi
  say "Resuming $EVIDENCE_STATUS for version $OLD_VERSION → $NEW_VERSION."
else
  OLD_VERSION="$VARIABLE_VERSION"
  OLD_STATE=$(gcloud secrets versions describe "$OLD_VERSION" \
    --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID" --format='value(state)')
  [[ "$OLD_STATE" == "ENABLED" ]] || { warn "current runtime secret version is not enabled"; exit 1; }
  [[ "$DEPLOYED_VERSION" == "$OLD_VERSION" ]] || {
    warn "deployed version $DEPLOYED_VERSION differs from GitHub version $OLD_VERSION"
    warn "reconcile the interrupted rotation before starting another one"
    exit 1
  }
fi
verify_backend_version "$DEPLOYED_VERSION" || {
  warn "the current backend does not satisfy private/readiness/provider controls"
  exit 1
}
say "Verified merged main, approved identities, immutable images, and backend version $DEPLOYED_VERSION."

# Create a distinct read-only key and store it as a new version without exposing it.
stage "Create or select the replacement runtime key"
if [[ -n "$RESUME_EVIDENCE" ]]; then
  say "Reusing replacement Secret Manager version $NEW_VERSION from the incomplete rotation."
else
  NEW_VERSION=$(gcloud secrets versions list "$RUNTIME_SECRET_ID" \
    --project="$PROJECT_ID" --filter='state=enabled' --sort-by='~createTime' \
    --limit=1 --format='value(name)')
  NEW_VERSION="${NEW_VERSION##*/}"
  if [[ "$NEW_VERSION" =~ ^[1-9][0-9]*$ && "$NEW_VERSION" != "$OLD_VERSION" ]] && \
    confirm "Reuse enabled, not-yet-deployed secret version $NEW_VERSION?"; then
    say "Reusing enabled replacement version $NEW_VERSION."
  else
    open_url "$QDRANT_CONSOLE_URL"
    step "Open finance-assistant-demo → API Keys and create a cluster-wide read-only key."
    step "Name it finance-assistant-staging-runtime-$(date -u +%Y%m%d%H%M%S) and prefer a 90-day expiration."
    open_url "https://console.cloud.google.com/security/secret-manager/secret/$RUNTIME_SECRET_ID/versions?project=$PROJECT_ID"
    step "Choose New version, paste only the new runtime key, and enable the version."
    pause "Return here after the enabled version exists. Press Enter to continue."
    NEW_VERSION=$(gcloud secrets versions list "$RUNTIME_SECRET_ID" \
      --project="$PROJECT_ID" --filter='state=enabled' --sort-by='~createTime' \
      --limit=1 --format='value(name)')
    NEW_VERSION="${NEW_VERSION##*/}"
  fi
  [[ "$NEW_VERSION" =~ ^[1-9][0-9]*$ && "$NEW_VERSION" != "$OLD_VERSION" ]] || {
    warn "no distinct enabled replacement version exists"
    exit 1
  }
  EVIDENCE="$EVIDENCE_DIR/staging-runtime-key-rotation-$REVISION-v$OLD_VERSION-to-v$NEW_VERSION.json"
fi
NEW_STATE=$(gcloud secrets versions describe "$NEW_VERSION" \
  --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID" --format='value(state)')
[[ "$NEW_STATE" == "ENABLED" ]] || { warn "replacement secret version is not enabled"; exit 1; }
say "Selected replacement version $NEW_VERSION without reading its payload into the shell."

# Validate exact collections/aliases and use a confirmed-absent DELETE for write denial.
stage "Qualify the replacement key without mutating Qdrant"
if [[ -f "$EVIDENCE" ]]; then
  jq -e --arg revision "$REVISION" --arg old "$OLD_VERSION" --arg new "$NEW_VERSION" '
    .revision == $revision and
    .rotation.old_secret_version == $old and
    .rotation.new_secret_version == $new and
    .secret_payloads_recorded == false
  ' "$EVIDENCE" >/dev/null || { warn "existing rotation evidence conflicts with this run"; exit 1; }
  say "Replacement-key qualification is already recorded as $(jq -r '.status' "$EVIDENCE")."
else
  "$PYTHON" -m ai_finance_assistant.knowledge.runtime_key_rotation \
    --repo-root "$REPO_ROOT" --contract "$CONTRACT" qualify-new-key \
    --runtime-api-key-file <(gcloud secrets versions access "$NEW_VERSION" \
      --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID") \
    --old-version "$OLD_VERSION" --new-version "$NEW_VERSION" \
    --evidence-path "$EVIDENCE"
fi
EVIDENCE_STATUS=$(jq -er '.status' "$EVIDENCE")
say "The replacement key reads both active aliases and receives HTTP 403 on a non-mutating write probe."

# Save and inspect the only permitted Terraform update before any apply.
stage "Plan the backend-only secret-version cutover"
case "$EVIDENCE_STATUS" in
  qualified_cutover_pending)
    prepare_rotation_plan "$OLD_VERSION" "$NEW_VERSION"
    "$PYTHON" -m ai_finance_assistant.knowledge.runtime_key_rotation \
      --repo-root "$REPO_ROOT" --contract "$CONTRACT" record-plan \
      --evidence-path "$EVIDENCE" --plan-json "$PLAN_JSON"
    EVIDENCE_STATUS="qualified_apply_pending"
    ;;
  qualified_apply_pending)
    if [[ "$DEPLOYED_VERSION" == "$OLD_VERSION" ]]; then
      prepare_rotation_plan "$OLD_VERSION" "$NEW_VERSION"
    else
      say "The backend already uses version $NEW_VERSION; resuming post-apply verification."
    fi
    ;;
  qualified_old_key_revocation_pending|qualified_old_secret_cleanup_pending|qualified)
    say "The reviewed cutover is already recorded; no Terraform plan is needed."
    ;;
  *) warn "unexpected rotation evidence status: $EVIDENCE_STATUS"; exit 1 ;;
esac

# Apply only the saved plan, then retain the old key unless every readback passes.
stage "Apply and verify the focused cutover"
if [[ "$EVIDENCE_STATUS" == "qualified_apply_pending" ]]; then
  if [[ "$DEPLOYED_VERSION" == "$OLD_VERSION" ]]; then
    confirm "Apply only the displayed backend secret-version plan?" || exit 1
    terraform -chdir="$WORKLOAD_ROOT" apply "$PLAN_FILE" || {
      warn "Terraform apply failed; the old key and secret version remain available."
      exit 1
    }
  fi
  if ! verify_backend_version "$NEW_VERSION"; then
    rollback_to_old_version || warn "automatic rollback was not completed"
    exit 1
  fi
  say "Backend version $NEW_VERSION is Ready, private, immutable-image pinned, and credential-free."
else
  say "Backend cutover verification is already recorded."
fi

# Publish the non-secret version selector only after deployed readback succeeds.
stage "Update and verify the GitHub version variable"
if [[ "$EVIDENCE_STATUS" == "qualified_apply_pending" ]]; then
  CURRENT_GITHUB_VERSION=$(gh variable get GCP_QDRANT_SECRET_VERSION \
    --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT")
  if [[ "$CURRENT_GITHUB_VERSION" == "$NEW_VERSION" ]]; then
    say "GitHub staging already selects version $NEW_VERSION; no variable write is needed."
  else
    [[ "$CURRENT_GITHUB_VERSION" == "$OLD_VERSION" ]] || {
      warn "GitHub version variable changed outside this reviewed rotation"
      exit 1
    }
    gh variable set GCP_QDRANT_SECRET_VERSION --repo "$REPOSITORY" \
      --env "$GITHUB_ENVIRONMENT" --body "$NEW_VERSION"
  fi
  VERIFIED_GITHUB_VERSION=$(gh variable get GCP_QDRANT_SECRET_VERSION \
    --repo "$REPOSITORY" --env "$GITHUB_ENVIRONMENT")
  [[ "$VERIFIED_GITHUB_VERSION" == "$NEW_VERSION" ]] || {
    warn "GitHub staging version readback did not match $NEW_VERSION"
    exit 1
  }
  refresh_backend_readback
  "$PYTHON" -m ai_finance_assistant.knowledge.runtime_key_rotation \
    --repo-root "$REPO_ROOT" --contract "$CONTRACT" record-cutover \
    --evidence-path "$EVIDENCE" \
    --backend-service-description "$SERVICE_DESCRIPTION_FILE" \
    --backend-iam-policy "$IAM_POLICY_FILE" \
    --expected-backend-image "$BACKEND_IMAGE" \
    --github-secret-version "$VERIFIED_GITHUB_VERSION"
  EVIDENCE_STATUS="qualified_old_key_revocation_pending"
else
  say "GitHub version $NEW_VERSION and the verified deployment are already recorded."
fi

# Only after cutover: revoke the old external key, prove rejection, and destroy its old copy.
stage "Retire the old runtime key and complete evidence"
if [[ "$EVIDENCE_STATUS" == "qualified_old_key_revocation_pending" ]]; then
  warn "Revoke the prior runtime key for Secret Manager version $OLD_VERSION, not replacement version $NEW_VERSION."
  open_url "$QDRANT_CONSOLE_URL"
  step "Open finance-assistant-demo → API Keys and revoke only the prior read-only runtime key."
  pause "Return here after Qdrant shows the old key revoked. Press Enter to verify."
  "$PYTHON" -m ai_finance_assistant.knowledge.runtime_key_rotation \
    --repo-root "$REPO_ROOT" --contract "$CONTRACT" finalize-old-key-revocation \
    --old-runtime-api-key-file <(gcloud secrets versions access "$OLD_VERSION" \
      --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID") \
    --evidence-path "$EVIDENCE"
  EVIDENCE_STATUS="qualified_old_secret_cleanup_pending"
fi
if [[ "$EVIDENCE_STATUS" == "qualified_old_secret_cleanup_pending" ]]; then
  OLD_STATE=$(gcloud secrets versions describe "$OLD_VERSION" \
    --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID" --format='value(state)')
  if [[ "$OLD_STATE" != "DESTROYED" ]]; then
    confirm "Permanently destroy old runtime secret version $OLD_VERSION in Secret Manager?" || exit 1
    gcloud secrets versions destroy "$OLD_VERSION" \
      --secret="$RUNTIME_SECRET_ID" --project="$PROJECT_ID" --quiet
  else
    say "Old runtime secret version $OLD_VERSION is already destroyed."
  fi
  "$PYTHON" -m ai_finance_assistant.knowledge.runtime_key_rotation \
    record-old-secret-destroyed --evidence-path "$EVIDENCE"
  EVIDENCE_STATUS="qualified"
fi
jq -e --arg new "$NEW_VERSION" '
  .status == "qualified" and
  .rotation.new_secret_version == $new and
  .new_runtime_permission.passed == true and
  .new_runtime_permission.write_status == 403 and
  .terraform_plan.only_qdrant_secret_version_changed == true and
  .deployed_backend.passed == true and
  .deployed_backend.provider_boundary.passed == true and
  .github_variable.readback_matches == true and
  .old_runtime_key.qdrant_revoked == true and
  .old_runtime_key.secret_version_destroyed == true and
  .provider_boundary.provider_mode == "credential_free" and
  .provider_boundary.model_mode == "credential_free" and
  .secret_payloads_recorded == false
' "$EVIDENCE" >/dev/null
say "Runtime-key rotation evidence is qualified and contains no credential payload."
note "$EVIDENCE"

finish
}

run_wizard "$@"; exit
